import fs from "node:fs";
import path from "node:path";
import type { ReferenceLang } from "@/types/cpp";

/**
 * Offline reference data. Generated by `pnpm import:cppreference` (see
 * scripts/import-cppreference.mjs) from the cppreference offline archive:
 *
 *   data/reference/      C++ pages (en/cpp)   routes /w/cpp/<path>
 *   data/reference-c/    C pages   (en/c)     routes /w/c/<path>
 *
 * Each root holds:
 *   index.json          ReferenceIndexEntry[], depth-first tree order
 *   tree.json           the same tree as nested nodes (used by the checker)
 *   pages/<file>.json   ReferencePage
 *   md/<file>.md        the page as plain GitHub-flavoured markdown
 *
 * A page path is the cppreference wiki path below /w/<lang>/, e.g.
 * "container/vector/push_back"; the root page is "". The on-disk <file> is the
 * path with "*" written as "_star_" and '"' as "_q_", "_root" for the root, or
 * the entry's explicit `file` (used to resolve case-insensitive collisions such
 * as numeric/math/NAN vs numeric/math/nan).
 *
 * Nothing here touches the network: index.json is the single source of truth
 * for which reference pages exist (routes, 404s, sitemap, search, explore).
 */

const DATA_DIRS: Record<ReferenceLang, string> = {
  cpp: path.join(/* turbopackIgnore: true */ process.cwd(), "data", "reference"),
  c: path.join(/* turbopackIgnore: true */ process.cwd(), "data", "reference-c"),
};

export type ReferenceKind = "page" | "index" | "redirect";

export interface ReferenceIndexEntry {
  path: string;
  title: string;
  /** First path segment of nested pages, "" for top-level pages. */
  section: string;
  /** Plain text, at most 240 characters. */
  summary: string;
  /** Path of the parent in the tree; null only for the root. */
  parent: string | null;
  hasChildren: boolean;
  kind: ReferenceKind;
  /** Only for kind "redirect". */
  redirectTo?: string;
  /** On-disk file key, only when it differs from the default encoding. */
  file?: string;
}

export interface ReferenceHeading {
  depth: 2 | 3 | 4;
  text: string;
  id: string;
}

export interface ReferenceLink {
  path: string;
  title: string;
}

export interface ReferencePage {
  path: string;
  title: string;
  /** Title with cppreference markup (e.g. the greyed "std::vector<T>::" prefix). */
  titleHtml: string;
  originalUrl: string;
  section: string;
  kind: ReferenceKind;
  redirectTo?: string;
  /** Set when the archive only had this page under an alias of its real path. */
  canonicalPath?: string;
  summary: string;
  /** Sanitized HTML. Internal links point at /w/cpp/... or /w/c/..., external ones carry data-external="1". */
  html: string;
  headings: ReferenceHeading[];
  /** Root first, excluding the page itself. */
  breadcrumbs: ReferenceLink[];
  children: ReferenceLink[];
  /** e.g. ["C++11", "C++20"] or ["C99", "C11"], oldest first. */
  standards: string[];
  wordCount: number;
  codeBlockCount: number;
}

interface IndexData {
  entries: ReferenceIndexEntry[];
  byPath: Map<string, ReferenceIndexEntry>;
  childrenOf: Map<string, ReferenceIndexEntry[]>;
}

const indexCache = new Map<ReferenceLang, IndexData>();

function indexData(lang: ReferenceLang): IndexData {
  const cached = indexCache.get(lang);
  if (cached) return cached;
  const raw = fs.readFileSync(
    path.join(/* turbopackIgnore: true */ DATA_DIRS[lang], "index.json"),
    "utf8"
  );
  const entries = JSON.parse(raw) as ReferenceIndexEntry[];
  const byPath = new Map<string, ReferenceIndexEntry>();
  const childrenOf = new Map<string, ReferenceIndexEntry[]>();
  for (const e of entries) {
    byPath.set(e.path, e);
    if (e.parent === null) continue;
    // Same rule as tree.json: redirects only appear when they hold real pages.
    if (e.kind === "redirect" && !e.hasChildren) continue;
    const list = childrenOf.get(e.parent);
    if (list) list.push(e);
    else childrenOf.set(e.parent, [e]);
  }
  const data = { entries, byPath, childrenOf };
  indexCache.set(lang, data);
  return data;
}

/** No reference path contains "%", so route segments can always be decoded. */
function decodeSegment(seg: string): string {
  try {
    return decodeURIComponent(seg);
  } catch {
    return seg;
  }
}

/** "a/b", ["a", "b"] or percent-encoded route segments -> "a/b". */
export function normalizeReferencePath(p: string | string[] | undefined): string {
  const segs = Array.isArray(p) ? p : (p ?? "").split("/");
  return segs.filter(Boolean).map(decodeSegment).join("/");
}

function fileKey(entry: ReferenceIndexEntry): string {
  if (entry.file) return entry.file;
  if (entry.path === "") return "_root";
  return entry.path.replace(/\*/g, "_star_").replace(/"/g, "_q_");
}

/** All entries (pages, indexes and redirects) in depth-first tree order. */
export function getReferenceIndex(lang: ReferenceLang): ReferenceIndexEntry[] {
  return indexData(lang).entries;
}

/** Every entry that is a real page (not a redirect). */
export function listedReferenceEntries(lang: ReferenceLang): ReferenceIndexEntry[] {
  return getReferenceIndex(lang).filter((e) => e.kind !== "redirect");
}

/**
 * Pages to prerender. Paths that differ only by case (numeric/math/NAN and
 * numeric/math/nan) would write the same output file on a case-insensitive
 * filesystem (macOS), so only the first of each such group is prerendered;
 * the others render on request.
 */
export function prerenderedReferenceEntries(
  lang: ReferenceLang
): ReferenceIndexEntry[] {
  const seen = new Set<string>();
  return listedReferenceEntries(lang).filter((e) => {
    const key = e.path.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function getReferenceEntry(
  lang: ReferenceLang,
  p: string | string[] | undefined
): ReferenceIndexEntry | undefined {
  return indexData(lang).byPath.get(normalizeReferencePath(p));
}

/** One page, read from its own file. */
export function getReferencePageData(
  lang: ReferenceLang,
  entry: ReferenceIndexEntry
): ReferencePage {
  const file = path.join(
    /* turbopackIgnore: true */ DATA_DIRS[lang],
    "pages",
    `${fileKey(entry)}.json`
  );
  return JSON.parse(fs.readFileSync(file, "utf8")) as ReferencePage;
}

/** The importer's markdown rendering of a page. */
export function getReferenceMarkdown(
  lang: ReferenceLang,
  entry: ReferenceIndexEntry
): string {
  return fs.readFileSync(
    path.join(/* turbopackIgnore: true */ DATA_DIRS[lang], "md", `${fileKey(entry)}.md`),
    "utf8"
  );
}

/** Direct children in tree order (redirects only when they hold real pages). */
export function getReferenceChildren(
  lang: ReferenceLang,
  p: string | string[] | undefined
): ReferenceIndexEntry[] {
  return indexData(lang).childrenOf.get(normalizeReferencePath(p)) ?? [];
}

function encodePath(p: string): string {
  return p
    .split("/")
    .map((seg) =>
      encodeURIComponent(seg).replace(/%(3D|2B|2C|40|3A)/g, (m) =>
        decodeURIComponent(m)
      )
    )
    .join("/");
}

/** Site route: ("cpp", "") -> "/w/cpp", ("cpp", "utility/move") -> "/w/cpp/utility/move". */
export function referenceHref(
  lang: ReferenceLang,
  p: string,
  fragment?: string
): string {
  const clean = normalizeReferencePath(p);
  const base = clean ? `/w/${lang}/${encodePath(clean)}` : `/w/${lang}`;
  return fragment ? `${base}#${fragment}` : base;
}

/** The page on en.cppreference.com. */
export function referenceLiveUrl(lang: ReferenceLang, p: string): string {
  const clean = normalizeReferencePath(p);
  return `https://en.cppreference.com/w/${lang}${clean ? `/${encodePath(clean)}` : ""}`;
}
